struct Player {
    name: &'static str,
    points: u32,
    wins: u32,
}

fn main() {
    let mut players = vec![
        Player { name: "Zoe", points: 9, wins: 2 },
        Player { name: "Ava", points: 9, wins: 3 },
        Player { name: "Ian", points: 7, wins: 1 },
        Player { name: "Mia", points: 9, wins: 2 },
        Player { name: "Eli", points: 7, wins: 4 },
    ];

    players.sort_by(|a, b| {
        b.points
            .cmp(&a.points)
            .then_with(|| a.name.cmp(&b.name))
    });

