    let mut rank = 1;
    for i in 0..players.len() {
        if i > 0 && players[i].points != players[i - 1].points {
            rank += 1;
        }
        lines.push(format!(
            "{}. {} - {} pts ({} wins)",
            rank, players[i].name, players[i].points, players[i].wins
        ));
    }

    println!("{}", lines.join("\n"));
}

