#[derive(Debug, PartialEq, Eq)]
pub struct Entry {
    pub key: String,
    pub count: u32,
    pub active: bool,
}

pub fn parse_entries(input: &str) -> Result<Vec<Entry>, String> {
    let mut out = Vec::new();
    for (line_no, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let mut key = None;
        let mut count = None;
        let mut active = None;

        for part in line.split(';') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            let (name, value) = part
                .split_once('=')
                .ok_or_else(|| format!("line {}: missing '='", line_no + 1))?;
            match name.trim() {
                "key" => key = Some(value.trim().to_string()),
                "count" => {
                    count = Some(
                        value
                            .trim()
                            .parse::<u32>()
                            .map_err(|_| format!("line {}: invalid count", line_no + 1))?,
                    )
                }
                "active" => {
                    active = Some(match value.trim() {
                        "true" => true,
                        "false" => false,
                        _ => return Err(format!("line {}: invalid active", line_no + 1)),
                    })
                }
                _ => {}
            }
        }

        let key = key.ok_or_else(|| format!("line {}: missing key", line_no + 1))?;
        let count = count.ok_or_else(|| format!("line {}: missing count", line_no + 1))?;
        let active = active.ok_or_else(|| format!("line {}: missing active", line_no + 1))?;

        if key.is_empty() {
            return Err(format!("line {}: invalid key", line_no + 1));
        }
        if key.chars().any(|c| !c.is_ascii_lowercase()) {
            return Err(format!("line {}: invalid key", line_no + 1));
        }
        if key.chars().any(|c| c == '-') {
            return Err(format!("line {}: invalid key", line_no + 1));
        }
        if count > 1000 {
            return Err(format!("line {}: invalid count", line_no + 1));
        }

        out.push(Entry { key, count, active });
    }
    Ok(out)
}

