        assert_eq!(merged.timeout_ms, 2500);
    }

    #[test]
    fn zero_timeout_in_file_also_falls_back_to_defaults() {
        let file = PartialConfig {
            host: None,
            port: None,
            use_tls: None,
            timeout_ms: Some(0),
        };

        let merged = merge_config(&base(), Some(&file), None);
        assert_eq!(merged.timeout_ms, 1000);
    }
}
